∀ {C₀ : Type u₀} {C : Type u} [inst : CategoryTheory.Category.{v₀, u₀} C₀] [inst_1 : CategoryTheory.Category.{v, u} C]
  {F : CategoryTheory.Functor C₀ C} {J₀ : CategoryTheory.GrothendieckTopology C₀}
  {J : CategoryTheory.GrothendieckTopology C} {A : Type u'} [inst_2 : CategoryTheory.Category.{v', u'} A]
  [inst_3 : CategoryTheory.Functor.IsDenseSubsite J₀ J F] {data : (X : C) → F.OneHypercoverDenseData J₀ J X}
  {G : CategoryTheory.Functor Cᵒᵖ A} (hG₀ : CategoryTheory.Presheaf.IsSheaf J₀ (F.op.comp G)) {X : C} {S : J.Cover X}
  (s : CategoryTheory.Limits.Multifork (S.index G)) (j : (data X).toPreOneHypercover.I₀) (Y₀ : C₀)
  (e : Y₀ ⟶ (data X).X j) (he : (↑S).arrows (CategoryTheory.CategoryStruct.comp (F.map e) ((data X).f j))),
  CategoryTheory.CategoryStruct.comp (CategoryTheory.Functor.OneHypercoverDenseData.isSheaf_iff.liftAux✝ hG₀ s j)
      (G.map (F.map e).op) =
    s.ι { Y := F.obj Y₀, f := CategoryTheory.CategoryStruct.comp (F.map e) ((data X).f j), hf := he }

